  "summary": "The code contains a critical security vulnerability due to a hardcoded secret and performance bottlenecks caused by synchronous JWT operations. Overall code health is poor; I have refactored the module to use environment variables, asynchronous operations, and added JSDoc for better maintainability.",
  "fixed_code": "const jwt = require(\"jsonwebtoken\");\n\nconst JWT_SECRET = process.env.JWT_SECRET;\nconst TOKEN_EXPIRY = \"1h\";\n\n/**\n * @param {{id: string|number, role: string}} user\n * @returns {Promise<string>}\n */\nfunction issueToken(user) {\n    return new Promise((resolve, reject) => {\n        jwt.sign({ sub: user.id, role: user.role }, JWT_SECRET, { expiresIn: TOKEN_EXPIRY }, (err, token) => {\n            if (err) reject(err);\n            else resolve(token);\n        });\n    });\n}\n\n/**\n * @param {string} token\n * @returns {Promise<object>}\n */\nfunction verifyToken(token) {\n    return new Promise((resolve, reject) => {\n        jwt.verify(token, JWT_SECRET, (err, decoded) => {\n            if (err) reject(err);\n            else resolve(decoded);\n        });\n    });\n}\n\nmodule.exports = { issueToken, verifyToken };"
}
